// ==== tb/unit/tb_rr_arbiter.sv   (tests: U01)
// =============================================================================
`ifdef RUN_TB_RR_ARBITER
// @tests    U01
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module arb_tester #(
  parameter int N          = 4,
  parameter bit EXHAUSTIVE = 1'b1,
  parameter int CYCLES     = 10000
) (
  input  logic clk,
  input  logic rst_n,
  input  logic go,
  output logic done
);
  localparam int IW = (N > 1) ? $clog2(N) : 1;
  localparam logic [N-1:0] ALL = {N{1'b1}};

  logic [N-1:0]  req    = '0;
  logic [N-1:0]  mask   = '0;
  logic          hold   = 1'b0;
  logic          update = 1'b0;
  logic [N-1:0]  gnt;
  logic [IW-1:0] gidx;
  logic          gvld;

  rr_arbiter #(.N(N)) dut (
    .clk_i    (clk),
    .rst_ni   (rst_n),
    .req_i    (req),
    .mask_i   (mask),
    .hold_i   (hold),
    .update_i (update),
    .gnt_o    (gnt),
    .gnt_idx_o(gidx),
    .gnt_vld_o(gvld)
  );

  int m_ptr      = 0;      // highest-priority requester
  int m_last     = 0;      // last accepted winner
  bit m_last_vld = 1'b0;

  int sid;                 // random stream of this tester

  function automatic int model_grant(logic [N-1:0] r, logic [N-1:0] m, logic h);
    logic [N-1:0] e;
    int g;
    e = r & ~m;
    g = -1;
    if (h && m_last_vld && e[m_last]) g = m_last;
    else begin
      for (int k = 0; k < N; k++) begin
        if (g < 0 && e[(m_ptr + k) % N]) g = (m_ptr + k) % N;
      end
    end
    return g;
  endfunction

  longint unsigned c_hold = 0, c_mask = 0, c_wrap = 0, c_idle = 0, c_upd = 0;
  int wait_cnt [N];
  int wait_max = 0;
  int seen_idx;            // DUT grant index seen in the last check
  bit seen_vld;

  task automatic check_outputs(string ph);
    int            g;
    logic [N-1:0]  exp_oh;
    logic [IW-1:0] exp_idx;
    logic [N-1:0]  e;
    g       = model_grant(req, mask, hold);
    exp_oh  = '0;
    exp_idx = '0;
    if (g >= 0) begin
      exp_oh[g] = 1'b1;
      exp_idx   = IW'(g);
    end
    `TB_CHECK(gnt === exp_oh && gidx === exp_idx && gvld === (g >= 0),
      ("N=%0d %s: req=%b mask=%b hold=%0b (ptr %0d, last %0d/%0b): got gnt=%b idx=%0d vld=%b, expected winner %0d",
       N, ph, req, mask, hold, m_ptr, m_last, m_last_vld, gnt, gidx, gvld, g))
    seen_idx = int'(gidx);
    seen_vld = gvld;
    e = req & ~mask;
    if (g < 0) c_idle++;
    else if (hold && m_last_vld && e[m_last]) c_hold++;
    else if (g < m_ptr) c_wrap++;
    if (model_grant(req, '0, hold) != g) c_mask++;
  endtask

  task automatic model_clock();
    int           g;
    logic [N-1:0] e;
    bit           hh;
    e  = req & ~mask;
    g  = model_grant(req, mask, hold);
    hh = hold && m_last_vld && e[m_last];
    for (int i = 0; i < N; i++) begin
      if (!e[i] || hh) wait_cnt[i] = 0;
      else if (update && g >= 0) begin
        if (g == i) wait_cnt[i] = 0;
        else begin
          wait_cnt[i]++;
          if (wait_cnt[i] > wait_max) wait_max = wait_cnt[i];
          `TB_CHECK(wait_cnt[i] <= N - 1,
            ("N=%0d: requester %0d passed over %0d times in a row", N, i, wait_cnt[i]))
        end
      end
    end
    if (update && g >= 0) begin
      m_ptr      = (g + 1) % N;
      m_last     = g;
      m_last_vld = 1'b1;
      c_upd++;
    end
  endtask

  task automatic step(logic [N-1:0] r, logic [N-1:0] m, logic h, logic u, string ph);
    @(negedge clk);
    req = r; mask = m; hold = h; update = u;
    #1;
    check_outputs(ph);
    @(posedge clk);
    model_clock();
    #1;
  endtask

  task automatic probe(logic [N-1:0] r, logic [N-1:0] m, logic h);
    req = r; mask = m; hold = h; update = 1'b0;
    #1;
    check_outputs("exhaustive");
  endtask

  task automatic steer(int p);
    logic [N-1:0] oh;
    oh = '0;
    oh[(p + N - 1) % N] = 1'b1;
    step(oh, '0, 1'b0, 1'b1, "steer");
  endtask

  function automatic logic [N-1:0] rand_bits(real p);
    logic [N-1:0] v;
    for (int i = 0; i < N; i++) v[i] = tb_pkg::rng_chance(sid, p);
    return v;
  endfunction

  task automatic phase_exhaustive();
    logic [N-1:0] x, y;
    for (int s = -1; s < N; s++) begin          // s = -1: the state right after reset
      if (s >= 0) steer(s);
      for (int h = 0; h < 2; h++) begin
        if (N <= 5) begin
          for (int r = 0; r < (1 << N); r++)
            for (int m = 0; m < (1 << N); m++)
              probe(N'(r), N'(m), h[0]);
        end else begin
          for (int e = 0; e < (1 << N); e++)
            for (int k = 0; k < 4; k++) begin
              if (k == 0) begin
                x = '0;
                y = '0;
              end else begin
                x = rand_bits(0.5) & ~N'(e);
                y = rand_bits(0.5) & ~N'(e) & ~x;
              end
              probe(N'(e) | x, x | y, h[0]);
            end
        end
      end
    end
  endtask

  task automatic phase_rotation();
    int p;
    p = int'(tb_pkg::rng_below(sid, N));
    steer(p);
    for (int k = 0; k < 3 * N; k++) begin
      step(ALL, '0, 1'b0, 1'b1, "rotation");
      `TB_CHECK(seen_vld && seen_idx == (p + k) % N,
        ("N=%0d rotation: grant %0d, expected %0d", N, seen_idx, (p + k) % N))
    end
  endtask

  task automatic phase_hold();
    int           j;
    logic [N-1:0] m;
    j = int'(tb_pkg::rng_below(sid, N));
    steer(j);
    step(ALL, '0, 1'b0, 1'b1, "hold");           // j wins and is accepted
    for (int k = 0; k < 4; k++) begin
      step(ALL, '0, 1'b1, 1'b1, "hold");         // hold: j keeps winning
      `TB_CHECK(seen_vld && seen_idx == j, ("N=%0d hold: grant %0d, expected %0d", N, seen_idx, j))
    end
    if (N > 1) begin
      m    = '0;
      m[j] = 1'b1;
      step(ALL, m, 1'b1, 1'b0, "hold, holder masked");   // a masked holder loses the hold
      `TB_CHECK(seen_vld && seen_idx == (j + 1) % N,
        ("N=%0d hold with holder masked: grant %0d, expected %0d", N, seen_idx, (j + 1) % N))
      step(ALL & ~m, '0, 1'b1, 1'b1, "hold, holder gone"); // the holder stops requesting
      `TB_CHECK(seen_vld && seen_idx == (j + 1) % N,
        ("N=%0d hold released: grant %0d, expected %0d", N, seen_idx, (j + 1) % N))
    end
  endtask

  task automatic phase_random();
    real          p_req;
    logic [N-1:0] r_v, m_v;
    logic         h_v, u_v;
    for (int c = 0; c < CYCLES; c++) begin
      case ((c / 500) % 3)                        // sparse, medium, dense requests
        0:       p_req = 0.15;
        1:       p_req = 0.5;
        default: p_req = 0.9;
      endcase
      r_v = rand_bits(p_req);
      m_v = rand_bits(0.25);
      h_v = tb_pkg::rng_chance(sid, 0.3);
      u_v = tb_pkg::rng_chance(sid, 0.75);
      step(r_v, m_v, h_v, u_v, "random");
    end
  endtask

  initial begin
    done = 1'b0;
    for (int i = 0; i < N; i++) wait_cnt[i] = 0;
    wait (go === 1'b1);
    sid = N;
    tb_pkg::rng_init(sid);
    if (EXHAUSTIVE) phase_exhaustive();
    phase_rotation();
    phase_hold();
    phase_random();
    @(negedge clk);              // leave the DUT idle: other testers may still run
    req    = '0;
    hold   = 1'b0;
    update = 1'b0;
    tb_pkg::cover_bin($sformatf("N=%0d hold decides the grant", N), c_hold);
    tb_pkg::cover_bin($sformatf("N=%0d mask changes the winner", N), c_mask);
    if (N > 1) tb_pkg::cover_bin($sformatf("N=%0d grant wraps around past N-1", N), c_wrap);
    tb_pkg::cover_bin($sformatf("N=%0d nobody eligible", N), c_idle);
    tb_pkg::cover_bin($sformatf("N=%0d grants accepted", N), c_upd);
    tb_pkg::info($sformatf("N=%0d longest run of grants to others: %0d (bound %0d)", N, wait_max, N - 1));
    done = 1'b1;
  end

endmodule


module tb_rr_arbiter;
  logic       clk   = 1'b0;
  logic       rst_n = 1'b0;
  logic       go    = 1'b0;
  logic [9:0] done;

  always #5 clk = ~clk;

  arb_tester #(.N(1))                                  t_n1  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[0]));
  arb_tester #(.N(2))                                  t_n2  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[1]));
  arb_tester #(.N(3))                                  t_n3  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[2]));
  arb_tester #(.N(4))                                  t_n4  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[3]));
  arb_tester #(.N(5))                                  t_n5  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[4]));
  arb_tester #(.N(6))                                  t_n6  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[5]));
  arb_tester #(.N(7))                                  t_n7  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[6]));
  arb_tester #(.N(8))                                  t_n8  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[7]));
  arb_tester #(.N(12), .EXHAUSTIVE(1'b0))              t_n12 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[8]));
  arb_tester #(.N(20), .EXHAUSTIVE(1'b0), .CYCLES(20000)) t_n20 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[9]));

  `TB_DUMP(tb_rr_arbiter)

  initial tb_pkg::watchdog(10ms);

  initial begin
    tb_pkg::start("U01", "rr_arbiter: one grant, mask, rotation, hold");
    repeat (3) @(posedge clk);
    @(negedge clk);
    rst_n = 1'b1;
    go    = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_RR_ARBITER

// =============================================================================
// ==== tb/unit/tb_sync_fifo.sv   (tests: U02)
// =============================================================================
`ifdef RUN_TB_SYNC_FIFO
// @tests    U02
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module fifo_tester #(
  parameter int W      = 16,
  parameter int DEPTH  = 4,
  parameter bit LEGAL  = 1'b1,   // 1: legal requests only; 0: illegal ones too
  parameter int CYCLES = 10000,
  parameter int STREAM = 0       // random stream id, unique per tester
) (
  input  logic clk,
  input  logic rst_n,
  input  logic go,
  output logic done
);
  localparam int CW = $clog2(DEPTH + 1);

  logic          push  = 1'b0;
  logic          pop   = 1'b0;
  logic [W-1:0]  wdata = '0;
  logic [W-1:0]  rdata;
  logic          empty, full;
  logic [CW-1:0] count;

  sync_fifo #(.WIDTH(W), .DEPTH(DEPTH), .CHECK(LEGAL)) dut (
    .clk_i   (clk),
    .rst_ni  (rst_n),
    .push_i  (push),
    .wdata_i (wdata),
    .pop_i   (pop),
    .rdata_o (rdata),
    .empty_o (empty),
    .full_o  (full),
    .count_o (count)
  );

  logic [W-1:0] model [$];       // reference: a queue, oldest first
  longint unsigned c_full = 0, c_drained = 0, c_pp_full = 0, c_pp_mid = 0,
                   c_bad_push = 0, c_bad_pop = 0, n_push = 0;

  function automatic logic [W-1:0] rand_word();
    logic [W-1:0] v;
    tb_pkg::rng_t r;
    r = '0;
    for (int b = 0; b < W; b++) begin
      if (b % 64 == 0) r = tb_pkg::rng_next(STREAM);
      v[b] = r[b % 64];
    end
    return v;
  endfunction

  task automatic check_outputs(string ph);
    int sz;
    sz = model.size();
    `TB_CHECK(empty === (sz == 0) && full === (sz == DEPTH) && count === CW'(sz),
      ("D=%0d W=%0d %s: empty=%b full=%b count=%0d, model holds %0d", DEPTH, W, ph, empty, full, count, sz))
    if (sz > 0) begin
      `TB_CHECK(rdata === model[0],
        ("D=%0d W=%0d %s: rdata 'h%0h, oldest entry 'h%0h", DEPTH, W, ph, rdata, model[0]))
    end
  endtask

  task automatic step(bit pu, bit po, string ph);
    int sz;
    bit do_pop, do_push;
    logic [W-1:0] d;
    d = rand_word();
    @(negedge clk);
    push = pu; pop = po; wdata = d;
    #1;
    check_outputs(ph);
    sz = model.size();
    if (sz == DEPTH) c_full++;
    if (pu && po && sz == DEPTH) c_pp_full++;
    if (pu && po && sz > 0 && sz < DEPTH) c_pp_mid++;
    if (pu && !po && sz == DEPTH) c_bad_push++;
    if (po && sz == 0) c_bad_pop++;
    @(posedge clk);
    do_pop  = po && sz > 0;
    do_push = pu && (sz < DEPTH || do_pop);
    if (do_pop) void'(model.pop_front());
    if (do_push) begin
      model.push_back(d);
      n_push++;
    end
    if (do_pop && model.size() == 0) c_drained++;
    #1;
  endtask

  task automatic phase_fill_drain();
    for (int rep = 0; rep < 2; rep++) begin
      for (int i = 0; i < DEPTH; i++) step(1'b1, 1'b0, "fill");
      if (!LEGAL) step(1'b1, 1'b0, "push while full");
      for (int i = 0; i < DEPTH; i++) step(1'b0, 1'b1, "drain");
      if (!LEGAL) step(1'b0, 1'b1, "pop while empty");
    end
  endtask

  task automatic phase_full_throughput();
    for (int i = 0; i < DEPTH; i++) step(1'b1, 1'b0, "fill");
    for (int i = 0; i < 2 * DEPTH + 3; i++) step(1'b1, 1'b1, "push and pop while full");
    for (int i = 0; i < DEPTH; i++) step(1'b0, 1'b1, "drain");
  endtask

  task automatic phase_streaming();
    step(1'b1, 1'b0, "stream start");
    for (int i = 0; i < 2 * DEPTH + 3; i++) step(1'b1, 1'b1, "stream");
    step(1'b0, 1'b1, "stream end");
  endtask

  task automatic phase_random();
    real p_push, p_pop;
    bit  pu, po;
    for (int c = 0; c < CYCLES; c++) begin
      case ((c / 250) % 4)
        0:       begin p_push = 0.8; p_pop = 0.2; end   // filling
        1:       begin p_push = 0.2; p_pop = 0.8; end   // draining
        2:       begin p_push = 0.5; p_pop = 0.5; end   // balanced
        default: begin p_push = 0.9; p_pop = 0.9; end   // busy
      endcase
      po = tb_pkg::rng_chance(STREAM, p_pop);
      pu = tb_pkg::rng_chance(STREAM, p_push);
      if (LEGAL) begin
        po = po && model.size() > 0;
        pu = pu && (model.size() < DEPTH || po);
      end
      step(pu, po, "random");
    end
  endtask

  string tag;     // label for coverage lines

  initial begin
    done = 1'b0;
    if (LEGAL) tag = $sformatf("D=%0d W=%0d legal", DEPTH, W);
    else       tag = $sformatf("D=%0d W=%0d illegal", DEPTH, W);
    wait (go === 1'b1);
    tb_pkg::rng_init(STREAM);
    phase_fill_drain();
    phase_full_throughput();
    phase_streaming();
    phase_random();
    @(negedge clk);              // leave the DUT idle: other testers may still run
    push = 1'b0;
    pop  = 1'b0;
    tb_pkg::cover_bin({tag, ": cycles full"}, c_full);
    tb_pkg::cover_bin({tag, ": drained to empty"}, c_drained);
    tb_pkg::cover_bin({tag, ": push and pop while full"}, c_pp_full);
    if (DEPTH > 1) tb_pkg::cover_bin({tag, ": push and pop part full"}, c_pp_mid);
    tb_pkg::cover_bin({tag, ": pointer wraps"}, n_push / longint'(DEPTH));
    if (!LEGAL) begin
      tb_pkg::cover_bin({tag, ": push while full ignored"}, c_bad_push);
      tb_pkg::cover_bin({tag, ": pop while empty ignored"}, c_bad_pop);
    end
    done = 1'b1;
  end

endmodule


module tb_sync_fifo;
  import noc_pkg::*;

  logic        clk   = 1'b0;
  logic        rst_n = 1'b0;
  logic        go    = 1'b0;
  logic [10:0] done;

  always #5 clk = ~clk;

  fifo_tester #(.DEPTH(1),  .STREAM(1))  t_d1  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[0]));
  fifo_tester #(.DEPTH(2),  .STREAM(2))  t_d2  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[1]));
  fifo_tester #(.DEPTH(3),  .STREAM(3))  t_d3  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[2]));
  fifo_tester #(.DEPTH(4),  .STREAM(4))  t_d4  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[3]));
  fifo_tester #(.DEPTH(5),  .STREAM(5))  t_d5  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[4]));
  fifo_tester #(.DEPTH(8),  .STREAM(8))  t_d8  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[5]));
  fifo_tester #(.DEPTH(25), .STREAM(25)) t_d25 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[6]));
  fifo_tester #(.W(FLIT_W), .DEPTH(5), .STREAM(105)) t_vc (.clk(clk), .rst_n(rst_n), .go(go), .done(done[7]));
  fifo_tester #(.DEPTH(1),  .LEGAL(1'b0), .STREAM(201)) t_i1  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[8]));
  fifo_tester #(.DEPTH(5),  .LEGAL(1'b0), .STREAM(205)) t_i5  (.clk(clk), .rst_n(rst_n), .go(go), .done(done[9]));
  fifo_tester #(.DEPTH(25), .LEGAL(1'b0), .STREAM(225)) t_i25 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[10]));

  `TB_DUMP(tb_sync_fifo)

  initial tb_pkg::watchdog(10ms);

  initial begin
    tb_pkg::start("U02", "sync_fifo: order and count under simultaneous push and pop");
    repeat (3) @(posedge clk);
    @(negedge clk);
    rst_n = 1'b1;
    go    = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_SYNC_FIFO

// =============================================================================
// ==== tb/unit/tb_route_compute.sv   (tests: U03)
// =============================================================================
`ifdef RUN_TB_ROUTE_COMPUTE
// @tests    U03
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module rc_tester
  import noc_pkg::*;
#(
  parameter int N         = 4,
  parameter bit ADAPT_ALL = 1'b1,   // all free-VC combinations on the productive ports
  parameter bit WALKS     = 1'b1    // hop-by-hop walks for every pair
) (
  input  logic go,
  output logic done
);
  coord_t                          cx   = '0;
  coord_t                          cy   = '0;
  node_id_t                        dst  = '0;
  logic                            mode = MODE_XY;
  logic [NPORTS-1:0][VC_CNT_W-1:0] free = '0;
  port_t                           p_xy, p_dor, p_ad;

  route_compute #(.MESH_N(N), .ALGO(RT_XY)) u_xy (
    .cur_x_i(cx), .cur_y_i(cy), .dst_i(dst), .mode_i(mode), .free_vc_i(free), .port_o(p_xy));
  route_compute #(.MESH_N(N), .ALGO(RT_DOR)) u_dor (
    .cur_x_i(cx), .cur_y_i(cy), .dst_i(dst), .mode_i(mode), .free_vc_i(free), .port_o(p_dor));
  route_compute #(.MESH_N(N), .ALGO(RT_ADAPTIVE)) u_ad (
    .cur_x_i(cx), .cur_y_i(cy), .dst_i(dst), .mode_i(mode), .free_vc_i(free), .port_o(p_ad));

  int sid;   // random stream

  longint unsigned c_port [3][NPORTS];   // [XY, YX, adaptive][port] choices seen
  longint unsigned c_y_more = 0, c_tie = 0, c_x_more = 0, c_one_dim = 0;

  function automatic int iabs(int v);
    return (v < 0) ? -v : v;
  endfunction

  function automatic port_t ref_dor(int x, int y, int tx, int ty, bit yx);
    int    dx, dy;
    port_t r;
    dx = tx - x;
    dy = ty - y;
    if (dx == 0 && dy == 0)  r = P_L;
    else if (!yx && dx != 0) r = (dx > 0) ? P_E : P_W;
    else if (!yx)            r = (dy > 0) ? P_S : P_N;
    else if (dy != 0)        r = (dy > 0) ? P_S : P_N;
    else                     r = (dx > 0) ? P_E : P_W;
    return r;
  endfunction

  function automatic port_t ref_adaptive(int x, int y, int tx, int ty,
                                         logic [NPORTS-1:0][VC_CNT_W-1:0] f);
    int    dx, dy;
    port_t px, py, r;
    dx = tx - x;
    dy = ty - y;
    px = (dx > 0) ? P_E : P_W;
    py = (dy > 0) ? P_S : P_N;
    if (dx == 0 && dy == 0) r = P_L;
    else if (dx == 0)       r = py;
    else if (dy == 0)       r = px;
    else                    r = (f[py] > f[px]) ? py : px;   // strictly more free VCs, else X
    return r;
  endfunction

  function automatic bit step_is_minimal(int x, int y, int tx, int ty, port_t p);
    int nx, ny;
    bit ok;
    nx = x;
    ny = y;
    ok = 1'b1;
    if (x == tx && y == ty) return (p == P_L);
    case (p)
      P_N:     ny = y - 1;
      P_E:     nx = x + 1;
      P_S:     ny = y + 1;
      P_W:     nx = x - 1;
      default: ok = 1'b0;       // Local before arrival, or not a port
    endcase
    return ok && (iabs(tx - nx) + iabs(ty - ny) == iabs(tx - x) + iabs(ty - y) - 1);
  endfunction

  function automatic void randomize_free();
    for (int p = 0; p < NPORTS; p++) free[p] = VC_CNT_W'(tb_pkg::rng_below(sid, MAX_VC + 1));
  endfunction

  task automatic probe_pair(int x, int y, int t);
    int    tx, ty;
    port_t px, py, exp;
    tx   = t % N;
    ty   = t / N;
    cx   = coord_t'(x);
    cy   = coord_t'(y);
    dst  = node_id_t'(t);
    randomize_free();

    mode = MODE_XY;
    #1;
    `TB_CHECK(p_xy === ref_dor(x, y, tx, ty, 1'b0),
      ("%0dx%0d XY at (%0d,%0d) to (%0d,%0d): got %s", N, N, x, y, tx, ty, tb_pkg::port_name(p_xy)))
    `TB_CHECK(p_dor === ref_dor(x, y, tx, ty, 1'b0),
      ("%0dx%0d DOR/XY at (%0d,%0d) to (%0d,%0d): got %s", N, N, x, y, tx, ty, tb_pkg::port_name(p_dor)))
    `TB_CHECK(p_ad === ref_adaptive(x, y, tx, ty, free),
      ("%0dx%0d adaptive at (%0d,%0d) to (%0d,%0d), free N%0d E%0d S%0d W%0d: got %s", N, N, x, y, tx, ty,
       free[P_N], free[P_E], free[P_S], free[P_W], tb_pkg::port_name(p_ad)))
    `TB_CHECK(step_is_minimal(x, y, tx, ty, p_xy) && step_is_minimal(x, y, tx, ty, p_ad),
      ("%0dx%0d at (%0d,%0d) to (%0d,%0d): a choice is not minimal (XY %s, adaptive %s)", N, N, x, y, tx, ty,
       tb_pkg::port_name(p_xy), tb_pkg::port_name(p_ad)))
    `TB_CHECK(dor_port(cx, cy, coord_t'(tx), coord_t'(ty), MODE_XY) === ref_dor(x, y, tx, ty, 1'b0),
      ("noc_pkg::dor_port XY wrong at (%0d,%0d) to (%0d,%0d)", x, y, tx, ty))
    `TB_CHECK(hops(cx, cy, coord_t'(tx), coord_t'(ty)) == iabs(tx - x) + iabs(ty - y),
      ("noc_pkg::hops wrong for (%0d,%0d) to (%0d,%0d)", x, y, tx, ty))
    c_port[0][p_xy]++;
    c_port[2][p_ad]++;
    if ((x == tx) != (y == ty)) c_one_dim++;

    mode = MODE_YX;
    #1;
    `TB_CHECK(p_dor === ref_dor(x, y, tx, ty, 1'b1),
      ("%0dx%0d DOR/YX at (%0d,%0d) to (%0d,%0d): got %s", N, N, x, y, tx, ty, tb_pkg::port_name(p_dor)))
    `TB_CHECK(step_is_minimal(x, y, tx, ty, p_dor),
      ("%0dx%0d YX at (%0d,%0d) to (%0d,%0d): %s is not minimal", N, N, x, y, tx, ty, tb_pkg::port_name(p_dor)))
    `TB_CHECK(p_xy === ref_dor(x, y, tx, ty, 1'b0) && p_ad === ref_adaptive(x, y, tx, ty, free),
      ("%0dx%0d at (%0d,%0d) to (%0d,%0d): RT_XY or RT_ADAPTIVE changed with mode_i", N, N, x, y, tx, ty))
    `TB_CHECK(dor_port(cx, cy, coord_t'(tx), coord_t'(ty), MODE_YX) === ref_dor(x, y, tx, ty, 1'b1),
      ("noc_pkg::dor_port YX wrong at (%0d,%0d) to (%0d,%0d)", x, y, tx, ty))
    c_port[1][p_dor]++;

    if (x != tx && y != ty) begin
      px = (tx > x) ? P_E : P_W;
      py = (ty > y) ? P_S : P_N;
      for (int fx = 0; fx <= MAX_VC; fx++) begin
        for (int fy = 0; fy <= MAX_VC; fy++) begin
          if (ADAPT_ALL || (fx == int'(free[px]) && fy == int'(free[py]))) begin
            randomize_free();
            free[px] = VC_CNT_W'(fx);
            free[py] = VC_CNT_W'(fy);
            #1;
            exp = (fy > fx) ? py : px;
            `TB_CHECK(p_ad === exp,
              ("%0dx%0d adaptive at (%0d,%0d) to (%0d,%0d), free %s=%0d %s=%0d: got %s, expected %s", N, N,
               x, y, tx, ty, tb_pkg::port_name(px), fx, tb_pkg::port_name(py), fy,
               tb_pkg::port_name(p_ad), tb_pkg::port_name(exp)))
            if (fy > fx) c_y_more++;
            else if (fy == fx) c_tie++;
            else c_x_more++;
          end
        end
      end
    end
  endtask

  task automatic walk(int s, int t, int algo);
    int    x, y, tx, ty, manh, n_hops;
    bit    moved_x, moved_y, arrived;
    port_t p;
    x       = s % N;
    y       = s / N;
    tx      = t % N;
    ty      = t / N;
    manh    = iabs(tx - x) + iabs(ty - y);
    n_hops  = 0;
    moved_x = 1'b0;
    moved_y = 1'b0;
    arrived = 1'b0;
    mode    = (algo == 1) ? MODE_YX : MODE_XY;
    dst     = node_id_t'(t);
    for (int h = 0; h <= manh && !arrived; h++) begin
      cx = coord_t'(x);
      cy = coord_t'(y);
      if (algo == 2) randomize_free();
      #1;
      p = (algo == 0) ? p_xy : ((algo == 1) ? p_dor : p_ad);
      if (p == P_L) arrived = 1'b1;
      else begin
        if (algo == 0 && moved_y && (p == P_E || p == P_W))
          tb_pkg::fail($sformatf("%0dx%0d XY walk %0d->%0d turns from Y back to X", N, N, s, t));
        if (algo == 1 && moved_x && (p == P_N || p == P_S))
          tb_pkg::fail($sformatf("%0dx%0d YX walk %0d->%0d turns from X back to Y", N, N, s, t));
        case (p)
          P_N:     begin y = y - 1; moved_y = 1'b1; end
          P_S:     begin y = y + 1; moved_y = 1'b1; end
          P_E:     begin x = x + 1; moved_x = 1'b1; end
          P_W:     begin x = x - 1; moved_x = 1'b1; end
          default: tb_pkg::fail($sformatf("%0dx%0d walk %0d->%0d: port %0d", N, N, s, t, p));
        endcase
        n_hops++;
      end
    end
    `TB_CHECK(arrived && x == tx && y == ty && n_hops == manh,
      ("%0dx%0d walk %0d->%0d (algo %0d): ended at (%0d,%0d) after %0d hops, arrived=%0b, distance %0d",
       N, N, s, t, algo, x, y, n_hops, arrived, manh))
  endtask

  task automatic check_pkg_helpers();
    int x, y, nx, ny;
    bit exp_has;
    for (int id = 0; id < N * N; id++) begin
      x = id % N;
      y = id / N;
      `TB_CHECK(id_x(node_id_t'(id), N) == coord_t'(x) && id_y(node_id_t'(id), N) == coord_t'(y) &&
                xy_to_id(coord_t'(x), coord_t'(y), N) == node_id_t'(id),
        ("%0dx%0d: id %0d <-> (x, y) wrong", N, N, id))
      for (int p = 0; p < NPORTS; p++) begin
        nx = x;
        ny = y;
        case (p)
          0:       ny = y - 1;
          1:       nx = x + 1;
          2:       ny = y + 1;
          3:       nx = x - 1;
          default: ;
        endcase
        exp_has = (nx >= 0 && nx < N && ny >= 0 && ny < N);
        `TB_CHECK(has_nbr(coord_t'(x), coord_t'(y), port_t'(p), N) === exp_has,
          ("%0dx%0d: has_nbr(%0d,%0d,%s) wrong", N, N, x, y, tb_pkg::port_name(port_t'(p))))
        if (exp_has && p != int'(P_L)) begin
          `TB_CHECK(nbr_id(node_id_t'(id), port_t'(p), N) == node_id_t'(ny * N + nx),
            ("%0dx%0d: nbr_id(%0d,%s) wrong", N, N, id, tb_pkg::port_name(port_t'(p))))
          `TB_CHECK(nbr_id(nbr_id(node_id_t'(id), port_t'(p), N), opposite(port_t'(p)), N) == node_id_t'(id),
            ("%0dx%0d: going %s and back from %0d does not return", N, N, tb_pkg::port_name(port_t'(p)), id))
        end
      end
    end
  endtask

  initial begin
    done = 1'b0;
    for (int a = 0; a < 3; a++) for (int p = 0; p < NPORTS; p++) c_port[a][p] = 0;
    wait (go === 1'b1);
    sid = 1000 + N;
    tb_pkg::rng_init(sid);
    check_pkg_helpers();
    for (int y = 0; y < N; y++)
      for (int x = 0; x < N; x++)
        for (int t = 0; t < N * N; t++)
          probe_pair(x, y, t);
    if (WALKS) begin
      for (int s = 0; s < N * N; s++)
        for (int t = 0; t < N * N; t++)
          for (int a = 0; a < 3; a++)
            walk(s, t, a);
    end
    for (int p = 0; p < NPORTS; p++) begin
      tb_pkg::cover_bin($sformatf("%0dx%0d XY chooses %s", N, N, tb_pkg::port_name(port_t'(p))), c_port[0][p]);
      tb_pkg::cover_bin($sformatf("%0dx%0d YX chooses %s", N, N, tb_pkg::port_name(port_t'(p))), c_port[1][p]);
      tb_pkg::cover_bin($sformatf("%0dx%0d adaptive chooses %s", N, N, tb_pkg::port_name(port_t'(p))), c_port[2][p]);
    end
    if (N > 1) begin
      tb_pkg::cover_bin($sformatf("%0dx%0d adaptive: Y has more free VCs", N, N), c_y_more);
      tb_pkg::cover_bin($sformatf("%0dx%0d adaptive: tie goes to X", N, N), c_tie);
      tb_pkg::cover_bin($sformatf("%0dx%0d adaptive: X has more free VCs", N, N), c_x_more);
      tb_pkg::cover_bin($sformatf("%0dx%0d only one productive direction", N, N), c_one_dim);
    end
    done = 1'b1;
  end

endmodule


module tb_route_compute;
  import noc_pkg::*;

  logic       go = 1'b0;
  logic [3:0] done;

  rc_tester #(.N(2))                                     t_2  (.go(go), .done(done[0]));
  rc_tester #(.N(4))                                     t_4  (.go(go), .done(done[1]));
  rc_tester #(.N(8))                                     t_8  (.go(go), .done(done[2]));
  rc_tester #(.N(16), .ADAPT_ALL(1'b0), .WALKS(1'b0))    t_16 (.go(go), .done(done[3]));

  `TB_DUMP(tb_route_compute)

  initial tb_pkg::watchdog(100ms);

  task automatic check_package();
    head_t  h;
    flit_t  f;
    logic [FLIT_DATA_W-1:0] d;
    `TB_CHECK($bits(head_t) == FLIT_DATA_W, ("head_t is %0d bits, not %0d", $bits(head_t), FLIT_DATA_W))
    `TB_CHECK(FLIT_W == 134 && LA_W == 16 && CX_W == 10 && CREDIT_W == 4,
      ("link widths: flit %0d, lookahead %0d, cancel %0d, credit %0d", FLIT_W, LA_W, CX_W, CREDIT_W))
    `TB_CHECK(is_head(FT_HEAD) && !is_tail(FT_HEAD) && !is_head(FT_BODY) && !is_tail(FT_BODY) &&
              !is_head(FT_TAIL) && is_tail(FT_TAIL) && is_head(FT_SINGLE) && is_tail(FT_SINGLE),
      ("flit type helpers wrong"))
    for (int p = 0; p < NPORTS; p++) begin
      `TB_CHECK(opposite(opposite(port_t'(p))) == port_t'(p) &&
                (p == int'(P_L) || opposite(port_t'(p)) != port_t'(p)),
        ("opposite(%0d) wrong", p))
    end
    h          = '0;
    h.dst      = 8'hA5;
    h.src      = 8'h3C;
    h.cls      = CLS_DATA;
    h.len      = 3'd5;
    h.seq      = 32'h1234_5678;
    h.t_create = 32'h9ABC_DEF0;
    h.check    = 32'h0F0F_0F0F;
    d          = h;
    `TB_CHECK(d[7:0] == 8'hA5 && d[15:8] == 8'h3C && d[16] == 1'b1 && d[23:21] == 3'd5 &&
              d[55:24] == 32'h1234_5678 && d[87:56] == 32'h9ABC_DEF0 && d[119:88] == 32'h0F0F_0F0F &&
              d[127:120] == 8'h00 && d[20:17] == 4'h0,
      ("head_t field positions differ from the documented layout: %h", d))
    f       = '0;
    f.vld   = 1'b1;
    f.ftype = FT_SINGLE;
    f.data  = d;
    `TB_CHECK(f[FLIT_W-1] == 1'b1 && f[FLIT_DATA_W-1:0] == d, ("flit_t layout differs: vld on top, data at the bottom"))
  endtask

  initial begin
    tb_pkg::start("U03", "route_compute: minimal ports; adaptive by free VCs, ties to X; XY and YX exact");
    check_package();
    go = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_ROUTE_COMPUTE

// =============================================================================
// ==== tb/unit/tb_switch_allocator.sv   (tests: U04)
// =============================================================================
`ifdef RUN_TB_SWITCH_ALLOCATOR
// @tests    U04
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module sa_tester
  import noc_pkg::*;
#(
  parameter int V      = 4,
  parameter int CYCLES = 10000
) (
  input  logic clk,
  input  logic rst_n,
  input  logic go,
  output logic done
);
  logic   [NPORTS-1:0][V-1:0] req       = '0;
  port_t  [NPORTS-1:0][V-1:0] port      = '0;
  logic   [NPORTS-1:0][V-1:0] active    = '0;
  vc_id_t [NPORTS-1:0][V-1:0] outvc     = '0;
  logic   [NPORTS-1:0]        has_free  = '0;
  vc_id_t [NPORTS-1:0]        alloc_vc  = '0;
  logic   [NPORTS-1:0][V-1:0] credit_ok = '0;
  logic   [NPORTS-1:0]        in_mask   = '0;
  logic   [NPORTS-1:0]        out_mask  = '0;
  logic   [NPORTS-1:0]        in_gnt, out_gnt, out_alloc;
  vc_id_t [NPORTS-1:0]        in_vc, in_outvc, out_vc;

  switch_allocator #(.NUM_VC(V)) dut (
    .clk_i       (clk),
    .rst_ni      (rst_n),
    .req_i       (req),
    .port_i      (port),
    .active_i    (active),
    .outvc_i     (outvc),
    .has_free_i  (has_free),
    .alloc_vc_i  (alloc_vc),
    .credit_ok_i (credit_ok),
    .in_mask_i   (in_mask),
    .out_mask_i  (out_mask),
    .in_gnt_o    (in_gnt),
    .in_vc_o     (in_vc),
    .in_outvc_o  (in_outvc),
    .out_gnt_o   (out_gnt),
    .out_alloc_o (out_alloc),
    .out_vc_o    (out_vc)
  );

  int m_in_ptr  [NPORTS];   // per input: VC with the highest priority
  int m_out_ptr [NPORTS];   // per output: input with the highest priority
  int m_pick    [NPORTS];   // stage 1: VC chosen by each input, -1 none
  int m_win     [NPORTS];   // stage 2: input that wins each output, -1 none

  int sid;                  // random stream

  function automatic bit may_compete(int i, int v);
    int p;
    p = int'(port[i][v]);
    if (!req[i][v] || in_mask[i] || out_mask[p]) return 1'b0;
    if (active[i][v]) return credit_ok[p][int'(outvc[i][v])];
    return has_free[p];
  endfunction

  function automatic void model_eval();
    int v, i;
    for (int ii = 0; ii < NPORTS; ii++) begin
      m_pick[ii] = -1;
      for (int k = 0; k < V; k++) begin
        v = (m_in_ptr[ii] + k) % V;
        if (m_pick[ii] < 0 && may_compete(ii, v)) m_pick[ii] = v;
      end
    end
    for (int o = 0; o < NPORTS; o++) begin
      m_win[o] = -1;
      for (int k = 0; k < NPORTS; k++) begin
        i = (m_out_ptr[o] + k) % NPORTS;
        if (m_win[o] < 0 && m_pick[i] >= 0 && int'(port[i][m_pick[i]]) == o) m_win[o] = i;
      end
    end
  endfunction

  function automatic int model_outvc(int i);
    int v;
    v = m_pick[i];
    return active[i][v] ? int'(outvc[i][v]) : int'(alloc_vc[port[i][v]]);
  endfunction

  function automatic void model_update();
    for (int o = 0; o < NPORTS; o++) begin
      if (m_win[o] >= 0) begin
        m_out_ptr[o]       = (m_win[o] + 1) % NPORTS;
        m_in_ptr[m_win[o]] = (m_pick[m_win[o]] + 1) % V;   // only winners move
      end
    end
  endfunction

  longint unsigned c_conflict = 0, c_alloc = 0, c_active = 0, c_cred_block = 0,
                   c_free_block = 0, c_in_mask = 0, c_out_mask = 0, c_five = 0,
                   c_loser = 0;
  int wait_cnt [NPORTS][V];
  int wait_max = 0;
  bit fair_phase = 1'b0;

  task automatic check_cycle();
    int  n_out, gi, p, v, n_gnt, n_pick [NPORTS];
    model_eval();
    for (int i = 0; i < NPORTS; i++) begin
      bit exp_gnt;
      exp_gnt = (m_pick[i] >= 0) && (m_win[port[i][m_pick[i]]] == i);
      `TB_CHECK(in_gnt[i] === exp_gnt,
        ("V=%0d input %0d: in_gnt %b, model %b", V, i, in_gnt[i], exp_gnt))
      if (exp_gnt) begin
        `TB_CHECK(int'(in_vc[i]) == m_pick[i] && int'(in_outvc[i]) == model_outvc(i),
          ("V=%0d input %0d: VC %0d outVC %0d, model VC %0d outVC %0d", V, i, in_vc[i],
           in_outvc[i], m_pick[i], model_outvc(i)))
      end
    end
    for (int o = 0; o < NPORTS; o++) begin
      `TB_CHECK(out_gnt[o] === (m_win[o] >= 0),
        ("V=%0d output %0d: out_gnt %b, model winner %0d", V, o, out_gnt[o], m_win[o]))
      if (m_win[o] >= 0) begin
        gi = m_win[o];
        `TB_CHECK(out_alloc[o] === !active[gi][m_pick[gi]] && int'(out_vc[o]) == model_outvc(gi),
          ("V=%0d output %0d: alloc %b VC %0d, model alloc %b VC %0d", V, o, out_alloc[o],
           out_vc[o], !active[gi][m_pick[gi]], model_outvc(gi)))
      end else begin
        `TB_CHECK(out_alloc[o] === 1'b0, ("V=%0d output %0d: alloc without a grant", V, o))
      end
    end
    n_gnt = 0;
    for (int o = 0; o < NPORTS; o++) begin
      n_out = 0;
      for (int i = 0; i < NPORTS; i++) begin
        if (in_gnt[i] === 1'b1 && int'(port[i][in_vc[i]]) == o) n_out++;
      end
      `TB_CHECK(n_out == int'(out_gnt[o]),
        ("V=%0d output %0d: %0d inputs granted, out_gnt %b", V, o, n_out, out_gnt[o]))
    end
    for (int i = 0; i < NPORTS; i++) begin
      if (in_gnt[i] === 1'b1) begin
        n_gnt++;
        v = int'(in_vc[i]);
        p = int'(port[i][v]);
        `TB_CHECK(v < V && may_compete(i, v),
          ("V=%0d input %0d: VC %0d granted but it may not compete", V, i, v))
        `TB_CHECK(active[i][v] ? (in_outvc[i] == outvc[i][v]) : (in_outvc[i] == alloc_vc[p] && has_free[p]),
          ("V=%0d input %0d: output VC %0d is wrong", V, i, in_outvc[i]))
      end
    end
    for (int o = 0; o < NPORTS; o++) n_pick[o] = 0;
    for (int i = 0; i < NPORTS; i++) begin
      if (m_pick[i] >= 0) begin
        n_pick[port[i][m_pick[i]]]++;
        if (m_win[port[i][m_pick[i]]] != i) c_loser++;
      end
      for (int vv = 0; vv < V; vv++) begin
        if (req[i][vv]) begin
          if (in_mask[i]) c_in_mask++;
          else if (out_mask[port[i][vv]]) c_out_mask++;
          else if (active[i][vv] && !credit_ok[port[i][vv]][int'(outvc[i][vv])]) c_cred_block++;
          else if (!active[i][vv] && !has_free[port[i][vv]]) c_free_block++;
        end
      end
      if (in_gnt[i] === 1'b1) begin
        if (active[i][int'(in_vc[i])]) c_active++; else c_alloc++;
      end
    end
    for (int o = 0; o < NPORTS; o++) if (n_pick[o] > 1) c_conflict++;
    if (n_gnt == NPORTS) c_five++;
  endtask

  function automatic void track_waits();
    for (int i = 0; i < NPORTS; i++) begin
      for (int v = 0; v < V; v++) begin
        if (in_gnt[i] === 1'b1 && int'(in_vc[i]) == v) wait_cnt[i][v] = 0;
        else begin
          wait_cnt[i][v]++;
          if (wait_cnt[i][v] > wait_max) wait_max = wait_cnt[i][v];
          `TB_CHECK(wait_cnt[i][v] < NPORTS * V,
            ("V=%0d input %0d VC %0d waited %0d cycles (bound %0d)", V, i, v, wait_cnt[i][v], NPORTS * V))
        end
      end
    end
  endfunction

  function automatic void randomize_inputs(real p_req);
    for (int i = 0; i < NPORTS; i++) begin
      for (int v = 0; v < V; v++) begin
        req[i][v]       = tb_pkg::rng_chance(sid, p_req);
        port[i][v]      = port_t'(tb_pkg::rng_below(sid, NPORTS));
        active[i][v]    = tb_pkg::rng_chance(sid, 0.5);
        outvc[i][v]     = vc_id_t'(tb_pkg::rng_below(sid, V));
        credit_ok[i][v] = tb_pkg::rng_chance(sid, 0.75);
      end
      has_free[i] = tb_pkg::rng_chance(sid, 0.75);
      alloc_vc[i] = vc_id_t'(tb_pkg::rng_below(sid, V));
      in_mask[i]  = tb_pkg::rng_chance(sid, 0.08);
      out_mask[i] = tb_pkg::rng_chance(sid, 0.08);
    end
  endfunction

  task automatic step();
    #1;
    check_cycle();
    if (fair_phase) track_waits();
    @(posedge clk);
    model_update();
    @(negedge clk);
  endtask

  initial begin
    real p_req;
    done = 1'b0;
    for (int i = 0; i < NPORTS; i++) begin
      m_in_ptr[i]  = 0;
      m_out_ptr[i] = 0;
      for (int v = 0; v < V; v++) wait_cnt[i][v] = 0;
    end
    wait (go === 1'b1);
    sid = 3000 + V;
    tb_pkg::rng_init(sid);
    @(negedge clk);
    for (int c = 0; c < CYCLES; c++) begin
      case ((c / 500) % 4)
        0:       p_req = 0.15;
        1:       p_req = 0.4;
        2:       p_req = 0.7;
        default: p_req = 0.95;
      endcase
      randomize_inputs(p_req);
      step();
    end
    for (int i = 0; i < NPORTS; i++) begin
      for (int v = 0; v < V; v++) begin
        req[i][v]       = 1'b1;
        port[i][v]      = port_t'(tb_pkg::rng_below(sid, NPORTS));
        active[i][v]    = tb_pkg::rng_chance(sid, 0.5);
        outvc[i][v]     = vc_id_t'(tb_pkg::rng_below(sid, V));
        credit_ok[i][v] = 1'b1;
      end
      has_free[i] = 1'b1;
      in_mask[i]  = 1'b0;
      out_mask[i] = 1'b0;
    end
    fair_phase = 1'b1;
    for (int c = 0; c < 40 * NPORTS * V; c++) step();
    fair_phase = 1'b0;
    req = '0;
    tb_pkg::cover_bin($sformatf("V=%0d two or more inputs want one output", V), c_conflict);
    tb_pkg::cover_bin($sformatf("V=%0d a stage-1 winner loses its output", V), c_loser);
    tb_pkg::cover_bin($sformatf("V=%0d head granted with a new output VC", V), c_alloc);
    tb_pkg::cover_bin($sformatf("V=%0d flit granted on its held output VC", V), c_active);
    tb_pkg::cover_bin($sformatf("V=%0d request blocked: no credit", V), c_cred_block);
    tb_pkg::cover_bin($sformatf("V=%0d request blocked: no idle output VC", V), c_free_block);
    tb_pkg::cover_bin($sformatf("V=%0d request blocked: input masked", V), c_in_mask);
    tb_pkg::cover_bin($sformatf("V=%0d request blocked: output masked", V), c_out_mask);
    tb_pkg::cover_bin($sformatf("V=%0d five grants in one cycle", V), c_five);
    tb_pkg::info($sformatf("V=%0d longest wait with persistent requests: %0d cycles (bound %0d)",
                           V, wait_max, NPORTS * V));
    done = 1'b1;
  end

endmodule


module tb_switch_allocator;
  logic       clk   = 1'b0;
  logic       rst_n = 1'b0;
  logic       go    = 1'b0;
  logic [3:0] done;

  always #5 clk = ~clk;

  sa_tester #(.V(1)) t_v1 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[0]));
  sa_tester #(.V(2)) t_v2 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[1]));
  sa_tester #(.V(3)) t_v3 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[2]));
  sa_tester #(.V(4)) t_v4 (.clk(clk), .rst_n(rst_n), .go(go), .done(done[3]));

  `TB_DUMP(tb_switch_allocator)

  initial tb_pkg::watchdog(10ms);

  initial begin
    tb_pkg::start("U04", "switch_allocator: one grant per input and output, VCs, masks, no starvation");
    repeat (3) @(posedge clk);
    @(negedge clk);
    rst_n = 1'b1;
    go    = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_SWITCH_ALLOCATOR

// =============================================================================
// ==== tb/unit/tb_router.sv   (tests: R01 R02 R03 R04)
// =============================================================================
`ifdef RUN_TB_ROUTER
// @tests    R01 R02 R03 R04
`timescale 1ns/1ps
// `include "tb_macros.svh": inlined earlier in this bundle

module rt_tester
  import noc_pkg::*;
#(
  parameter int V    = 4,       // VCs per port
  parameter int ALGO = RT_XY,   // regular routing of the router
  parameter int TID  = 1        // tester number: packet ids and random streams
) (
  input  logic clk,
  input  logic rst_n,
  input  logic go,
  output logic done
);
  localparam int MN       = 4;  // 4x4 mesh
  localparam int RX       = 1;  // router under test at (1,1)
  localparam int RY       = 1;
  localparam int DEPTH    = 5;  // flits per VC
  localparam int LAT_HOP  = 4;  // zero load: flit on the input link -> on the output link
  localparam int LAT_CRED = 2;  // zero load: flit on the input link -> its credit back
  localparam logic [2:0] EXP_ANY = 3'd7;   // expected port decided by the test

  flit_t   [NPORTS-1:0] in_flit  = '0;   // driven by the source models
  credit_t [NPORTS-1:0] in_cred;          // DUT -> source models
  flit_t   [NPORTS-1:0] out_flit;         // DUT -> sink models
  credit_t [NPORTS-1:0] out_cred = '0;   // driven by the sink models

  la_t [3:0] unused_la;     // lookahead outputs, zero in design A
  cx_t [3:0] unused_cx;     // cancel token outputs, zero in design A
  la_t       unused_lal;    // lookahead for the NI, zero in design A

  router #(
    .MESH_N   (MN),
    .NUM_VC   (V),
    .VC_DEPTH (DEPTH),
    .ALGO     (ALGO),
    .DESIGN   (DESIGN_A)
  ) dut (
    .clk_i        (clk),
    .rst_ni       (rst_n),
    .cur_x_i      (coord_t'(RX)),
    .cur_y_i      (coord_t'(RY)),
    .in_flit_i    (in_flit),
    .in_credit_o  (in_cred),
    .out_flit_o   (out_flit),
    .out_credit_i (out_cred),
    .in_la_i      ('0),
    .out_la_o     (unused_la),
    .in_cx_i      ('0),
    .out_cx_o     (unused_cx),
    .cx_inj_i     ('0),
    .la_loc_o     (unused_lal),
    .tx_go_i      (1'b0),
    .tx_dst_i     ('0),
    .tx_mode_i    (1'b0)
  );

  typedef struct packed {
    logic [31:0] id;       // tester, source port, sequence number
    logic [7:0]  dst;      // destination router
    logic [2:0]  len;      // flits, 1..5
    logic [2:0]  src;      // input port it enters on
    logic [2:0]  exp;      // output port it must leave on; EXP_ANY = checked by the test
    logic        any_vc;   // 1: the lowest idle input VC; 0: VC vc
    logic [1:0]  vc;
  } pkt_t;

  function automatic logic [31:0] sig32(logic [31:0] x);
    logic [63:0] z;
    z = tb_pkg::mix64({32'h0, x});
    return z[31:0] ^ z[63:32];
  endfunction

  function automatic logic [FLIT_DATA_W-1:0] payload(pkt_t p, int idx);
    head_t       h;
    logic [63:0] z;
    if (idx == 0) begin
      h       = '0;
      h.dst   = p.dst;
      h.src   = node_id_t'(p.src);
      h.len   = p.len;
      h.cls   = (p.len > 3'd1) ? CLS_DATA : CLS_CTRL;
      h.seq   = p.id;
      h.check = sig32(p.id);
      return h;
    end
    z = tb_pkg::mix64(64'(p) ^ {32'(idx), 32'h9e37_79b9});
    return {p.id, 32'(idx), z};
  endfunction

  function automatic ftype_t ftype_of(int idx, int len);
    if (len == 1)       return FT_SINGLE;
    if (idx == 0)       return FT_HEAD;
    if (idx == len - 1) return FT_TAIL;
    return FT_BODY;
  endfunction

  function automatic int dst_for(int q, int r);
    case (q)
      0:       return 1;                  // (1,0)
      1:       return (r % 2 != 0) ? 7 : 6;    // (3,1) or (2,1)
      2:       return (r % 2 != 0) ? 13 : 9;   // (1,3) or (1,2)
      3:       return 4;                  // (0,1)
      default: return 5;                  // (1,1): itself, the Local port
    endcase
  endfunction

  function automatic bit productive(int q, int dst);
    int dx, dy;
    dx = dst % MN - RX;
    dy = dst / MN - RY;
    case (q)
      0:       return dy < 0;             // N
      1:       return dx > 0;             // E
      2:       return dy > 0;             // S
      3:       return dx < 0;             // W
      default: return dx == 0 && dy == 0;
    endcase
  endfunction

  typedef logic [4:0] slot_t;    // per-VC queues: 32 entries
  typedef logic [2:0] pslot_t;   // per-port queue: 8 entries

  function automatic slot_t pv(int p, int v);
    if (p < 0 || p >= NPORTS || v < 0 || v >= V) $fatal(1, "pv: port %0d VC %0d out of range", p, v);
    return slot_t'(p * 4 + v);
  endfunction

  function automatic pslot_t pq(int p);
    if (p < 0 || p >= NPORTS) $fatal(1, "pq: port %0d out of range", p);
    return pslot_t'(p);
  endfunction

  pkt_t        sb_pkt   [int unsigned];       // every packet sent, by id
  int          sb_port  [int unsigned];       // port it arrived on, -1 not yet
  bit          sb_done  [int unsigned];       // tail arrived
  int unsigned sb_tsend [longint unsigned];   // cycle flit (id, idx) was on the input link
  int          sb_left = 0;                   // packets not yet complete at a sink
  int          seq [NPORTS];
  int unsigned cyc = 0;                       // cycle number
  bit          chk_lat = 1'b0;                // R01: zero-load timing checks

  always @(posedge clk) cyc <= cyc + 1;

  function automatic int unsigned send(int src, int dst, int len, logic [2:0] exp, bit any_vc, int vc);
    pkt_t p;
    int   n;
    `TB_CHECK(src >= 0 && src < NPORTS && dst >= 0 && dst < MN * MN && len >= 1 &&
              len <= MAX_PKT_FLITS && vc >= 0 && vc < V,
      ("T%0d send: bad packet src %0d dst %0d len %0d vc %0d", TID, src, dst, len, vc))
    p.id     = {8'(TID), 3'(src), 21'(seq[src])};
    seq[src] = seq[src] + 1;
    p.dst    = 8'(dst);
    p.len    = 3'(len);
    p.src    = 3'(src);
    p.exp    = exp;
    p.any_vc = any_vc;
    p.vc     = 2'(vc);
    sb_pkt[p.id]  = p;
    sb_port[p.id] = -1;
    sb_done[p.id] = 1'b0;
    sb_left++;
    n = txq[pq(src)].size();
    txq[pq(src)].push_back(p);
    `TB_CHECK(txq[pq(src)].size() == n + 1, ("T%0d send: packet %h was not queued at port %0d", TID, p.id, src))
    return p.id;
  endfunction

  pkt_t        txq    [8][$];          // packets waiting to start, at pq(port)
  bit          s_busy [NPORTS][4];     // input VC held (until its VC-free credit)
  int          s_cred [NPORTS][4];     // credits of the input VC
  bit          s_has  [NPORTS][4];     // packet in progress with flits left
  pkt_t        s_pkt  [NPORTS][4];
  int          s_idx  [NPORTS][4];     // next flit index
  int          s_rr   [NPORTS];
  real         s_rate [NPORTS];        // chance of sending in a cycle
  int unsigned s_ctq  [32][$];         // send cycles of flits whose credit is pending, at pv()
  int          sid_src, sid_snk, sid_tst;

  longint unsigned c_novc = 0, c_vcfree = 0;

  function automatic void sources_cycle();
    flit_t f;
    int    v, k;
    bit    sent, blocked;
    pkt_t  p;
    for (int sp = 0; sp < NPORTS; sp++) begin
      if (in_cred[sp].vld) begin
        v = int'(in_cred[sp].vc);
        `TB_CHECK(v < V, ("T%0d port %0d: credit for VC %0d", TID, sp, v))
        if (v < V) begin
          s_cred[sp][v]++;
          `TB_CHECK(s_cred[sp][v] <= DEPTH, ("T%0d port %0d VC %0d: %0d credits", TID, sp, v, s_cred[sp][v]))
          `TB_CHECK(s_ctq[pv(sp, v)].size() > 0, ("T%0d port %0d VC %0d: credit for no flit", TID, sp, v))
          if (s_ctq[pv(sp, v)].size() > 0) begin
            k = int'(cyc - s_ctq[pv(sp, v)][0]);
            void'(s_ctq[pv(sp, v)].pop_front());
            if (chk_lat) begin
              `TB_CHECK(k == LAT_CRED, ("T%0d port %0d VC %0d: credit after %0d cycles, expected %0d at zero load",
                                         TID, sp, v, k, LAT_CRED))
            end
          end
          if (in_cred[sp].vc_free) begin
            `TB_CHECK(s_busy[sp][v] && !s_has[sp][v] && s_cred[sp][v] == DEPTH,
              ("T%0d port %0d VC %0d: VC-free with busy=%0b flits left=%0b credits=%0d", TID, sp, v,
               s_busy[sp][v], s_has[sp][v], s_cred[sp][v]))
            s_busy[sp][v] = 1'b0;
            c_vcfree++;
          end
        end
      end
      f    = '0;
      sent = 1'b0;
      if (txq[pq(sp)].size() > 0) begin
        blocked = 1'b1;
        for (int vv = 0; vv < V; vv++) begin
          if (!s_busy[sp][vv] && (txq[pq(sp)][0].any_vc || int'(txq[pq(sp)][0].vc) == vv)) blocked = 1'b0;
        end
        if (blocked) c_novc++;
      end
      if (tb_pkg::rng_chance(sid_src, s_rate[sp])) begin
        for (int kk = 0; kk < V; kk++) begin
          v = (s_rr[sp] + kk) % V;
          if (!sent && s_has[sp][v] && s_cred[sp][v] > 0) begin
            sent = 1'b1;
          end else if (!sent && !s_busy[sp][v] && txq[pq(sp)].size() > 0 &&
                       (txq[pq(sp)][0].any_vc || int'(txq[pq(sp)][0].vc) == v)) begin
            p              = txq[pq(sp)][0];
            void'(txq[pq(sp)].pop_front());
            s_pkt[sp][v]   = p;
            s_idx[sp][v]   = 0;
            s_busy[sp][v]  = 1'b1;
            s_has[sp][v]   = 1'b1;
            sent           = 1'b1;
          end
          if (sent && f.vld == 1'b0) begin
            p       = s_pkt[sp][v];
            f.vld   = 1'b1;
            f.ftype = ftype_of(s_idx[sp][v], int'(p.len));
            f.vc    = vc_id_t'(v);
            f.data  = payload(p, s_idx[sp][v]);
            sb_tsend[{32'h0, p.id} * 8 + longint'(s_idx[sp][v])] = cyc;
            s_ctq[pv(sp, v)].push_back(cyc);
            s_cred[sp][v]--;
            s_idx[sp][v]++;
            if (s_idx[sp][v] == int'(p.len)) s_has[sp][v] = 1'b0;
            s_rr[sp] = (v + 1) % V;
          end
        end
      end
      in_flit[sp] = f;
    end
  endfunction

  typedef struct packed {
    ftype_t      ft;
    logic [31:0] t;
  } rxf_t;

  rxf_t        rxb     [32][$];        // buffer of output port q, VC v at pv(q, v)
  bit          k_alloc [NPORTS][4];    // VC holds a packet (head in, tail not yet read)
  int unsigned k_id    [NPORTS][4];
  int          k_cnt   [NPORTS][4];    // flits of that packet received
  int          k_rr    [NPORTS];
  real         k_rate  [NPORTS];       // chance of reading a flit in a cycle
  bit          k_hold  [NPORTS];       // read nothing
  int          k_last  [NPORTS];       // VC of the last flit on the output link

  longint unsigned c_full = 0, c_hold = 0, c_inter = 0, c_allvc = 0;
  longint unsigned c_outvc [4];

  function automatic void receive(int q, flit_t f);
    int          v, idx;
    int unsigned id;
    head_t       h, e;
    pkt_t        p;
    rxf_t        x;
    longint unsigned key;
    if (!f.vld) return;
    v = int'(f.vc);
    h = head_t'(f.data);
    `TB_CHECK(!f.byp, ("T%0d output %0d: bypass flit from a design-A router", TID, q))
    `TB_CHECK(v < V, ("T%0d output %0d: flit on VC %0d", TID, q, v))
    if (v >= V) return;
    `TB_CHECK(rxb[pv(q, v)].size() < DEPTH,
      ("T%0d output %0d VC %0d: overflow, the router sent without a credit", TID, q, v))
    if (rxb[pv(q, v)].size() == DEPTH - 1) c_full++;
    if (is_head(f.ftype)) begin
      `TB_CHECK(!k_alloc[q][v], ("T%0d output %0d VC %0d: new head while the VC still holds a packet", TID, q, v))
      id = h.seq;
      `TB_CHECK(sb_pkt.exists(id) != 0, ("T%0d output %0d: head of unknown packet %h", TID, q, id))
      if (sb_pkt.exists(id) == 0) return;
      `TB_CHECK(sb_port[id] == -1, ("T%0d output %0d: packet %h arrived twice", TID, q, id))
      `TB_CHECK(productive(q, int'(sb_pkt[id].dst)),
        ("T%0d packet %h to router %0d left on port %0d, off every minimal path", TID, id, sb_pkt[id].dst, q))
      k_alloc[q][v] = 1'b1;
      k_id[q][v]    = id;
      k_cnt[q][v]   = 0;
      sb_port[id]   = q;
      c_outvc[v]++;
      if (chk_lat) begin
        `TB_CHECK(v == 0, ("T%0d output %0d: at zero load a head takes VC 0, not %0d", TID, q, v))
      end
    end else begin
      `TB_CHECK(k_alloc[q][v] && k_cnt[q][v] > 0,
        ("T%0d output %0d VC %0d: body or tail without a head", TID, q, v))
      if (!(k_alloc[q][v] && k_cnt[q][v] > 0)) return;
    end
    if (k_last[q] >= 0 && k_last[q] != v) begin
      if (k_alloc[q][k_last[q]]) begin
        if (k_cnt[q][k_last[q]] < int'(sb_pkt[k_id[q][k_last[q]]].len)) c_inter++;
      end
    end
    k_last[q] = v;
    id  = k_id[q][v];
    idx = k_cnt[q][v];
    p   = sb_pkt[id];
    `TB_CHECK(idx < int'(p.len), ("T%0d output %0d VC %0d: packet %h has more than %0d flits", TID, q, v, id, p.len))
    `TB_CHECK(f.ftype == ftype_of(idx, int'(p.len)),
      ("T%0d output %0d VC %0d: flit %0d of packet %h has type %b", TID, q, v, idx, id, f.ftype))
    if (idx == 0) begin
      e = head_t'(payload(p, 0));
      `TB_CHECK(h == e,
        ("T%0d output %0d VC %0d: head of packet %h is corrupt (got/expected dst %0d/%0d src %0d/%0d len %0d/%0d check %h/%h)",
         TID, q, v, id, h.dst, e.dst, h.src, e.src, h.len, e.len, h.check, e.check))
    end else begin
      `TB_CHECK(f.data == payload(p, idx),
        ("T%0d output %0d VC %0d: flit %0d of packet %h is corrupt", TID, q, v, idx, id))
    end
    if (p.exp != EXP_ANY) begin
      `TB_CHECK(q == int'(p.exp), ("T%0d packet %h left on port %0d, expected %0d", TID, id, q, p.exp))
    end
    key = {32'h0, id} * 8 + longint'(idx);
    `TB_CHECK(sb_tsend.exists(key) != 0, ("T%0d packet %h flit %0d arrived before it was sent", TID, id, idx))
    if (chk_lat && sb_tsend.exists(key) != 0) begin
      `TB_CHECK(cyc - sb_tsend[key] == LAT_HOP,
        ("T%0d packet %h flit %0d: %0d cycles from input %0d to output %0d, expected %0d at zero load",
         TID, id, idx, cyc - sb_tsend[key], p.src, q, LAT_HOP))
    end
    k_cnt[q][v]++;
    x.ft = f.ftype;
    x.t  = cyc;
    rxb[pv(q, v)].push_back(x);
    if (is_tail(f.ftype)) begin
      `TB_CHECK(k_cnt[q][v] == int'(p.len), ("T%0d packet %h ended after %0d of %0d flits", TID, id, k_cnt[q][v], p.len))
      sb_done[id] = 1'b1;
      sb_left--;
    end
  endfunction

  function automatic void sinks_cycle();
    credit_t c;
    int      v;
    bit      popped, taken;
    for (int q = 0; q < NPORTS; q++) begin
      receive(q, out_flit[q]);
      taken = 1'b1;
      for (int vv = 0; vv < V; vv++) begin
        if (!k_alloc[q][vv]) taken = 1'b0;
      end
      if (taken) c_allvc++;
      c      = '0;
      popped = 1'b0;
      if (k_hold[q]) c_hold++;
      else if (tb_pkg::rng_chance(sid_snk, k_rate[q])) begin
        for (int kk = 0; kk < V; kk++) begin
          v = (k_rr[q] + kk) % V;
          if (!popped && rxb[pv(q, v)].size() > 0 && rxb[pv(q, v)][0].t < cyc) begin
            c.vld     = 1'b1;
            c.vc      = vc_id_t'(v);
            c.vc_free = is_tail(rxb[pv(q, v)][0].ft);
            if (c.vc_free) k_alloc[q][v] = 1'b0;
            void'(rxb[pv(q, v)].pop_front());
            popped  = 1'b1;
            k_rr[q] = (v + 1) % V;
          end
        end
      end
      out_cred[q] = c;
    end
  endfunction

  bit models_on = 1'b0;

  always @(negedge clk) begin
    if (models_on) begin
      sinks_cycle();
      sources_cycle();
    end
  end

  function automatic string algo_name();
    if (ALGO == RT_XY) return "XY";
    return "adaptive";
  endfunction

  function automatic bit all_idle();
    for (int sp = 0; sp < NPORTS; sp++) begin
      if (txq[pq(sp)].size() != 0) return 1'b0;
      for (int v = 0; v < V; v++) begin
        if (s_busy[sp][v] || s_has[sp][v] || s_cred[sp][v] != DEPTH) return 1'b0;
        if (k_alloc[sp][v] || rxb[pv(sp, v)].size() != 0) return 1'b0;
      end
    end
    return 1'b1;
  endfunction

  function automatic void set_rates(real src, real snk);
    for (int sp = 0; sp < NPORTS; sp++) begin
      s_rate[sp] = src;
      k_rate[sp] = snk;
      k_hold[sp] = 1'b0;
    end
  endfunction

  task automatic wait_idle(string what, int timeout);
    int t;
    t = 0;
    while (!(sb_left == 0 && all_idle()) && t < timeout) begin
      @(posedge clk);
      t++;
    end
    `TB_CHECK(sb_left == 0 && all_idle(),
      ("T%0d %s: not idle after %0d cycles, %0d packets still in flight", TID, what, timeout, sb_left))
  endtask

  task automatic wait_arrived(string what, int timeout);
    int t;
    t = 0;
    while (sb_left != 0 && t < timeout) begin
      @(posedge clk);
      t++;
    end
    `TB_CHECK(sb_left == 0, ("T%0d %s: %0d packets missing after %0d cycles", TID, what, sb_left, timeout))
  endtask

  task automatic test_r01();
    longint unsigned n;
    n = 0;
    tb_pkg::phase($sformatf("T%0d R01: every input to every output, every VC, 1 and 5 flits", TID));
    set_rates(1.0, 1.0);
    chk_lat = 1'b1;
    for (int sp = 0; sp < NPORTS; sp++)
      for (int q = 0; q < NPORTS; q++)
        for (int v = 0; v < V; v++)
          for (int l = 0; l < 2; l++) begin
            void'(send(sp, dst_for(q, v), (l == 0) ? 1 : MAX_PKT_FLITS, 3'(q), 1'b0, v));
            wait_idle("R01", 200);
            n++;
          end
    chk_lat = 1'b0;
    tb_pkg::cover_bin($sformatf("T%0d R01 input-output-VC-length cases", TID), n);
  endtask

  task automatic test_r02();
    int    q, len;
    real   rates [4];
    longint unsigned novc0, allvc0, hold0, full0;
    tb_pkg::phase($sformatf("T%0d R02: back-pressure from random sink stalls", TID));
    rates[0] = 0.1; rates[1] = 0.3; rates[2] = 0.6; rates[3] = 1.0;
    novc0   = c_novc;
    allvc0  = c_allvc;
    hold0   = c_hold;
    full0   = c_full;
    for (int sp = 0; sp < NPORTS; sp++) begin
      s_rate[sp] = 0.6 + 0.4 * real'(tb_pkg::rng_below(sid_tst, 5)) / 4.0;
      for (int n = 0; n < 300; n++) begin
        q   = int'(tb_pkg::rng_below(sid_tst, NPORTS));
        len = tb_pkg::rng_chance(sid_tst, 0.6) ? MAX_PKT_FLITS : 1;
        if (tb_pkg::rng_chance(sid_tst, 0.1)) len = 2 + int'(tb_pkg::rng_below(sid_tst, 3));
        void'(send(sp, dst_for(q, n), len, 3'(q), 1'b1, 0));
      end
    end
    for (int w = 0; w < 60; w++) begin
      for (int k = 0; k < NPORTS; k++) begin
        k_rate[k] = rates[tb_pkg::rng_below(sid_tst, 4)];
        k_hold[k] = tb_pkg::rng_chance(sid_tst, 0.3);
      end
      repeat (100) @(posedge clk);
    end
    set_rates(1.0, 1.0);
    wait_idle("R02", 20000);
    tb_pkg::cover_bin($sformatf("T%0d R02 a packet found every input VC busy (cycles)", TID), c_novc - novc0);
    tb_pkg::cover_bin($sformatf("T%0d R02 an output had every VC taken (cycles)", TID), c_allvc - allvc0);
    tb_pkg::cover_bin($sformatf("T%0d R02 a sink held its reads (cycles)", TID), c_hold - hold0);
    tb_pkg::cover_bin($sformatf("T%0d R02 a sink VC buffer filled to %0d flits", TID, DEPTH), c_full - full0);
  endtask

  task automatic test_r03();
    longint unsigned inter0;
    longint unsigned outvc0 [4];
    tb_pkg::phase($sformatf("T%0d R03: all inputs and VCs to one output, mixed lengths", TID));
    inter0 = c_inter;
    for (int v = 0; v < 4; v++) outvc0[v] = c_outvc[v];
    set_rates(1.0, 1.0);
    for (int q = 0; q < NPORTS; q++) begin
      for (int sp = 0; sp < NPORTS; sp++) begin
        for (int n = 0; n < 3 * V; n++) begin
          void'(send(sp, dst_for(q, n), (n % 3 == 0) ? 1 : ((n % 3 == 1) ? MAX_PKT_FLITS : 3), 3'(q), 1'b1, 0));
        end
      end
      wait_idle("R03", 5000);
    end
    if (V > 1) tb_pkg::cover_bin($sformatf("T%0d R03 flits of two packets interleaved on a link", TID), c_inter - inter0);
    for (int v = 0; v < V; v++)
      tb_pkg::cover_bin($sformatf("T%0d R03 output VC %0d used", TID, v), c_outvc[v] - outvc0[v]);
  endtask

  longint unsigned c_y_more = 0, c_tie = 0, c_x_more = 0, c_kept = 0;

  task automatic r04_case(int px, int py, int probe_src, int probe_dst, int kx, int ky, bit keep_test);
    int unsigned id;
    int          exp;
    int          t;
    k_hold[px] = 1'b1;
    k_hold[py] = 1'b1;
    for (int n = 0; n < kx; n++) void'(send(int'(P_L), dst_for(px, n), 1, 3'(px), 1'b1, 0));
    for (int n = 0; n < ky; n++) void'(send(int'(P_L), dst_for(py, n), 1, 3'(py), 1'b1, 0));
    wait_arrived("R04 occupy", 200);
    repeat (2) @(posedge clk);
    if (ALGO == RT_ADAPTIVE && (V - ky) > (V - kx)) exp = py;
    else                                            exp = px;
    if (ALGO == RT_ADAPTIVE) begin
      if ((V - ky) > (V - kx))      c_y_more++;
      else if ((V - ky) == (V - kx)) c_tie++;
      else                          c_x_more++;
    end
    id = send(probe_src, probe_dst, 1, EXP_ANY, 1'b1, 0);
    t  = 0;
    while (sb_tsend.exists({32'h0, id} * 8) == 0 && t < 100) begin
      @(posedge clk);
      t++;
    end
    @(posedge clk);                              // the probe's head is now in a VC
    if (keep_test) begin
      k_hold[py] = 1'b0;
      repeat (40) @(posedge clk);
      `TB_CHECK(sb_port[id] == -1,
        ("T%0d R04: the probe left on port %0d before its own port %0d had a free VC", TID, sb_port[id], px))
      c_kept++;
    end
    k_hold[px] = 1'b0;
    k_hold[py] = 1'b0;
    wait_idle("R04", 500);
    `TB_CHECK(sb_port[id] == exp,
      ("T%0d R04 %s: free VCs %0d behind port %0d, %0d behind port %0d: probe left on %0d, expected %0d",
       TID, algo_name(), V - kx, px, V - ky, py, sb_port[id], exp))
  endtask

  task automatic test_r04();
    tb_pkg::phase($sformatf("T%0d R04: route choice against free downstream VCs (%s)", TID, algo_name()));
    set_rates(1.0, 1.0);
    for (int kx = 0; kx <= V; kx++) begin
      for (int ky = 0; ky <= V; ky++) begin
        r04_case(int'(P_E), int'(P_S), int'(P_N), 10, kx, ky, 1'b0);   // to (2,2): E or S
        r04_case(int'(P_W), int'(P_N), int'(P_S), 0,  kx, ky, 1'b0);   // to (0,0): W or N
      end
    end
    r04_case(int'(P_E), int'(P_S), int'(P_W), 10, V, V, 1'b1);
    r04_case(int'(P_W), int'(P_N), int'(P_E), 0,  V, V, 1'b1);
    if (ALGO == RT_ADAPTIVE) begin
      tb_pkg::cover_bin($sformatf("T%0d R04 Y had more free VCs", TID), c_y_more);
      tb_pkg::cover_bin($sformatf("T%0d R04 tie, X taken", TID), c_tie);
      tb_pkg::cover_bin($sformatf("T%0d R04 X had more free VCs", TID), c_x_more);
    end
    tb_pkg::cover_bin($sformatf("T%0d R04 route kept while waiting for a VC", TID), c_kept);
  endtask

  initial begin
    done = 1'b0;
    for (int sp = 0; sp < NPORTS; sp++) begin
      seq[sp]    = 0;
      s_rr[sp]   = 0;
      k_rr[sp]   = 0;
      k_last[sp] = -1;
      for (int v = 0; v < 4; v++) begin
        s_busy[sp][v]  = 1'b0;
        s_has[sp][v]   = 1'b0;
        s_cred[sp][v]  = DEPTH;
        s_idx[sp][v]   = 0;
        k_alloc[sp][v] = 1'b0;
        k_id[sp][v]    = 0;
        k_cnt[sp][v]   = 0;
      end
    end
    for (int v = 0; v < 4; v++) c_outvc[v] = 0;
    set_rates(1.0, 1.0);
    wait (go === 1'b1);
    sid_src = 4000 + 4 * TID;
    sid_snk = sid_src + 1;
    sid_tst = sid_src + 2;
    tb_pkg::rng_init(sid_src);
    tb_pkg::rng_init(sid_snk);
    tb_pkg::rng_init(sid_tst);
    @(posedge clk);
    models_on = 1'b1;
    if (tb_pkg::test_on("R01")) test_r01();
    if (tb_pkg::test_on("R02")) test_r02();
    if (tb_pkg::test_on("R03")) test_r03();
    if (tb_pkg::test_on("R04")) test_r04();
    tb_pkg::info($sformatf("T%0d (V=%0d, %s): %0d packets checked, %0d VC-free credits", TID, V,
                           algo_name(), sb_pkt.num(), c_vcfree));
    `TB_CHECK(c_vcfree == longint'(sb_pkt.num()),
      ("T%0d: %0d packets but %0d VC-free credits", TID, sb_pkt.num(), c_vcfree))
    done = 1'b1;
  end

endmodule


module tb_router;
  import noc_pkg::*;

  logic       clk   = 1'b0;
  logic       rst_n = 1'b0;
  logic       go    = 1'b0;
  logic [3:0] done;

  always #5 clk = ~clk;

  rt_tester #(.V(4), .ALGO(RT_XY),       .TID(1)) t_v4_xy (.clk(clk), .rst_n(rst_n), .go(go), .done(done[0]));
  rt_tester #(.V(4), .ALGO(RT_ADAPTIVE), .TID(2)) t_v4_ad (.clk(clk), .rst_n(rst_n), .go(go), .done(done[1]));
  rt_tester #(.V(2), .ALGO(RT_ADAPTIVE), .TID(3)) t_v2_ad (.clk(clk), .rst_n(rst_n), .go(go), .done(done[2]));
  rt_tester #(.V(1), .ALGO(RT_XY),       .TID(4)) t_v1_xy (.clk(clk), .rst_n(rst_n), .go(go), .done(done[3]));

  `TB_DUMP(tb_router)

  initial tb_pkg::watchdog(20ms);

  initial begin
    tb_pkg::start("R01-R04", "router: ports, VCs, timing, back-pressure, interleaving, adaptive choice");
    repeat (3) @(posedge clk);
    @(negedge clk);
    rst_n = 1'b1;
    go    = 1'b1;
    wait (&done === 1'b1);
    tb_pkg::finish();
  end

endmodule
`endif // RUN_TB_ROUTER

